import{CHIPS,freshSave,validSave,price,trade,forge,equip,reward}from'./core.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let save=freshSave();try{const s=JSON.parse(localStorage.getItem('battle-net-v1'));if(validSave(s))save=s;}catch{}let filter='all',marketMode='buy',page='battle',selected=null,toastTimer;function persist(){try{localStorage.setItem('battle-net-v1',JSON.stringify(save));}catch{toast('Browser storage unavailable: progress lasts this session.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function go(id){if(id!=='battle'&&game.running&&!game.paused)pause();page=id;$$('.page').forEach(p=>p.classList.toggle('hidden',p.id!==id));$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===id));render();window.scrollTo({top:0,behavior:'smooth'});}
$$('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('#profile').onclick=()=>$('#help').showModal();$('#close-help').onclick=()=>$('#help').close();$('#reset').onclick=()=>{if(!confirm('Reset all local inventory, credits, and victories?'))return;save=freshSave();persist();game.running=false;game.paused=false;game.level=1;resetBattle();showOverlay('Ready to jack in?','Your demo save has been reset.','START BATTLE');$('#help').close();render();};
$$('.filter').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('.filter').forEach(t=>t.classList.toggle('active',t===b));render();});$$('.market-tab').forEach(b=>b.onclick=()=>{marketMode=b.dataset.mode;$$('.market-tab').forEach(t=>t.classList.toggle('active',t===b));render();});
function artPath(id){return `assets/${['buster','armor'].includes(id)?'equipment':'chips'}/${id==='gold'?'gold-longsword':id}.png`;}
function art(id){return `<div class="chip-art"><img src="${artPath(id)}" alt="${CHIPS[id].name}"></div>`;}
function card(id,extra=''){const c=CHIPS[id];return `<div class="chip ${id==='gold'?'gold':''}"><div class="chip-top"><span>${c.label}</span><span>× ${save.items[id]}</span></div>${art(id)}<div class="chip-info"><h3>${c.name}</h3><div><span>${c.type.toUpperCase()}</span><b>${c.damage} ${id==='recover'?'HP':id==='barrier'?'SHIELD':id==='armor'?'GUARD':'DMG'}</b></div>${extra}</div></div>`;}
function render(){ $('#balance').textContent=save.credits;$('#power').textContent=save.equipment.buster?'16':'12';$('#armor').textContent=save.equipment.armor?'Guard Frame':'Standard';$('#folder').innerHTML=save.folder.map((id,i)=>`<div class="folder-row"><span class="mini-icon">${CHIPS[id].icon}</span><span>${CHIPS[id].name}</span><span>${String(i+1).padStart(2,'0')}</span></div>`).join('');$('#hand').innerHTML=save.folder.map((id,i)=>`<button class="chip ${id==='gold'?'gold':''}" data-use="${i}" aria-label="Use ${CHIPS[id].name}, key ${i+1}"><div class="chip-top"><span>${CHIPS[id].label}</span><kbd>${i+1}</kbd></div>${art(id)}<div class="chip-info"><h3>${CHIPS[id].name}</h3><div><span>${id==='recover'?'RESTORE':id==='barrier'?'ABSORB':'DAMAGE'}</span><b>${CHIPS[id].damage}</b></div></div><div class="cooldown"></div></button>`).join('');$$('[data-use]').forEach(b=>b.onclick=()=>useChip(+b.dataset.use));
const ids=Object.keys(CHIPS).filter(id=>save.items[id]>0&&(filter==='all'||CHIPS[id].type===filter));$('#collection-count').textContent=`${Object.values(save.items).reduce((a,b)=>a+b,0)} chips owned · ${save.wins} victories`;$('#inventory').innerHTML=ids.map(id=>card(id,`<p>${CHIPS[id].desc}</p><button class="secondary" data-equip="${id}">${CHIPS[id].type==='equipment'?(save.equipment[id]?'UNEQUIP':'EQUIP GEAR'):'ADD TO FOLDER'} ↗</button>`)).join('')||'<p>No chips in this category yet. Visit the marketplace.</p>';$$('[data-equip]').forEach(b=>b.onclick=()=>{if(game.running){toast('Finish your battle before changing loadout.');return;}const id=b.dataset.equip;if(CHIPS[id].type==='equipment'){equip(save,id);persist();render();toast('Equipment updated');return;}selected=id;$('#equip-panel').innerHTML=`<h3>Place ${CHIPS[id].name} in a slot</h3>${save.folder.map((c,i)=>`<button class="secondary slot" data-slot="${i}">${i+1} · ${CHIPS[c].name}</button>`).join('')}`;$$('[data-slot]').forEach(t=>t.onclick=()=>{equip(save,selected,+t.dataset.slot);persist();render();$('#equip-panel').innerHTML='<h3>Folder updated</h3><p>Your chip is ready for the next battle.</p>';});$('#equip-panel').scrollIntoView({behavior:'smooth',block:'nearest'});});
$('#market-items').innerHTML=Object.keys(CHIPS).filter(id=>marketMode==='buy'||save.items[id]>0).map(id=>card(id,`<p>${CHIPS[id].desc}</p><div title="Prices rise as the merchant inventory shrinks; sell price is 65% of buy price."><span>MERCHANT STOCK ${save.stock[id]}</span><b>${price(save,id,marketMode)} CR</b></div><button class="secondary" data-trade="${id}">${marketMode.toUpperCase()} FOR ${price(save,id,marketMode)} CREDITS ↗</button>`)).join('');$$('[data-trade]').forEach(b=>b.onclick=()=>{const result=trade(save,b.dataset.trade,marketMode);if(result.ok){persist();render();}toast(result.message);});$('#forge-owned').textContent=`${save.items.longsword} / 100 OWNED`;$('#forge-requirement').textContent=save.items.longsword>=100?'Your duplicates are ready for a new life.':`${100-save.items.longsword} more Longswords needed. Battle or trade to collect them.`;$('#forge-btn').disabled=save.items.longsword<100||game.running;}
$('#forge-btn').onclick=()=>{const result=forge(save);if(result.ok){persist();render();beep(700,.3);}toast(result.message);};
const sprites={};for(const [id,file]of Object.entries({pulse:'pulse-idle',enemy:'hex-guard-idle'})){const img=new Image();img.src=`assets/sprites/${file}.png`;sprites[id]=img;}
const canvas=$('#arena'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;const game={running:false,paused:false,level:1,p:{x:1,y:1,hp:300,shield:0,inv:0},e:{x:4,y:1,hp:240,max:240},time:0,shotAt:-1,enemyAt:1.4,moveAt:0,warn:null,shots:[],fx:[],cooldowns:[0,0,0,0,0]};let last=0,keys=new Set(),audio=null,sound=false;$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'SOUND ON':'SOUND OFF';if(sound){audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();beep(600,.1);}};function beep(f,d=.08){if(!sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.value=f;g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d);}
function resetBattle(){Object.assign(game,{time:0,shotAt:-1,enemyAt:1.5,moveAt:0,warn:null,shots:[],fx:[],cooldowns:[0,0,0,0,0]});game.p={x:1,y:1,hp:300,shield:0,inv:0};const max=240+(game.level-1)*60;game.e={x:4,y:1,hp:max,max};$('#sector').textContent=`SECTOR ${String(game.level).padStart(2,'0')}`;hud();}
function showOverlay(title,text,label){$('#overlay').classList.remove('hidden');$('#overlay h2').textContent=title;$('#overlay p').textContent=text;$('#start').innerHTML=`${label} <span>↗</span>`;}
function start(){if(game.paused){game.paused=false;$('#overlay').classList.add('hidden');$('#pause').textContent='Ⅱ Pause';return;}resetBattle();game.running=true;$('#overlay').classList.add('hidden');beep(440,.15);render();}
$('#start').onclick=start;function pause(){if(!game.running)return;game.paused=!game.paused;keys.clear();if(game.paused)showOverlay('Connection paused','Take a breath. The grid will wait.','RESUME BATTLE');else $('#overlay').classList.add('hidden');$('#pause').textContent=game.paused?'▷ Resume':'Ⅱ Pause';}$('#pause').onclick=pause;document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.running&&!game.paused)pause();});
function callout(msg){$('#callout').textContent=msg;clearTimeout(callout.timer);callout.timer=setTimeout(()=>$('#callout').textContent='',1700);}
function hud(){$('#hp').textContent=game.p.hp;$('#enemyhp').textContent=game.e.hp;$('#enemymax').textContent=game.e.max;$('#hpbar').style.width=`${game.p.hp/3}%`;$('#enemybar').style.width=`${game.e.hp/game.e.max*100}%`;}
function finish(win){game.running=false;keys.clear();if(win){reward(save);persist();game.level++;showOverlay('Virus deleted.', '+30 credits · +5 Longswords. Your next sector awaits.','NEXT SECTOR');beep(900,.3);}else{showOverlay('Connection lost.','No chips lost. Rethink your folder and jack back in.','TRY AGAIN');beep(130,.3);}hud();render();}
function hitEnemy(d){game.e.hp=Math.max(0,game.e.hp-d);game.fx.push({type:'hit',x:game.e.x,y:game.e.y,t:.35,text:`−${d}`});beep(300,.05);hud();if(game.e.hp===0)finish(true);}
function hitPlayer(d){if(game.p.inv>0)return;d=Math.max(0,d-(save.equipment.armor?5:0));const absorbed=Math.min(d,game.p.shield);game.p.shield-=absorbed;d-=absorbed;game.p.hp=Math.max(0,game.p.hp-d);game.p.inv=.45;game.fx.push({type:'hurt',x:game.p.x,y:game.p.y,t:.4,text:d?`−${d}`:'BLOCK'});beep(130,.1);hud();if(game.p.hp===0)finish(false);}
function shoot(){if(game.time-game.shotAt<.28)return;game.shotAt=game.time;game.shots.push({x:game.p.x+.3,y:game.p.y,v:8,damage:save.equipment.buster?16:12,kind:'buster'});beep(600,.035);}
function useChip(i){if(!game.running||game.paused){toast('Start a battle to use your chips.');return;}if(game.cooldowns[i]>0){callout('Chip reloading…');return;}const id=save.folder[i],c=CHIPS[id];game.cooldowns[i]=8;callout(c.name.toUpperCase());if(id==='recover'){game.p.hp=Math.min(300,game.p.hp+60);game.fx.push({type:'heal',x:game.p.x,y:game.p.y,t:.7,text:'+60'});hud();}else if(id==='barrier'){game.p.shield=50;}else if(id==='thunder'){game.fx.push({type:'thunder',x:game.e.x,y:game.e.y,t:.5});hitEnemy(c.damage);}else if(id==='longsword'||id==='gold'){game.fx.push({type:id,x:game.p.x+.8,y:game.p.y,t:.4});if(game.e.y===game.p.y&&game.e.x-game.p.x<=2)hitEnemy(80);else callout('Out of range! Move forward and align.');}else{game.shots.push({x:game.p.x+.4,y:game.p.y,v:7,damage:40,kind:'cannon'});}beep(750,.15);}
window.addEventListener('keydown',e=>{if(page!=='battle'||$('#help').open||e.target.matches('input,textarea,select'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','w','a','s','d','1','2','3','4','5','Escape'].includes(e.key)){e.preventDefault();if(e.key==='Escape'&&!e.repeat)pause();else if(/^[1-5]$/.test(e.key)&&!e.repeat)useChip(+e.key-1);else keys.add(e.key.toLowerCase());}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();if(game.running&&!game.paused)pause();});
canvas.addEventListener('pointerdown',e=>{if(!game.running||game.paused)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*1000,y=(e.clientY-r.top)/r.height*490;let best=null,dist=1e9;for(let row=0;row<3;row++)for(let col=0;col<3;col++){const p=pos(col,row);const d=Math.hypot(p.x-x,p.y-y);if(d<dist){dist=d;best={col,row};}}game.p.x=best.col;game.p.y=best.row;});if(matchMedia('(pointer:coarse)').matches){const controls=document.createElement('div');controls.className='touch-controls';controls.innerHTML='<button data-dir="up">↑</button><button data-dir="left">←</button><button data-dir="down">↓</button><button data-dir="right">→</button><button data-dir="fire">FIRE</button>';$('.arena-shell').append(controls);controls.querySelectorAll('button').forEach(b=>{const key={up:'w',left:'a',down:'s',right:'d',fire:' '}[b.dataset.dir];b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(key);};b.onpointerup=b.onpointercancel=()=>keys.delete(key);});}
function update(dt){game.time+=dt;game.p.inv=Math.max(0,game.p.inv-dt);game.cooldowns=game.cooldowns.map(t=>Math.max(0,t-dt));if(game.time>=game.moveAt){let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(dx||dy){game.p.x=Math.max(0,Math.min(2,game.p.x+dx));game.p.y=Math.max(0,Math.min(2,game.p.y+dy));game.moveAt=game.time+.14;}}if(keys.has(' '))shoot();if(!game.warn&&game.time>=game.enemyAt){game.e.y=Math.floor(Math.random()*3);game.e.x=Math.random()>.65?3:4;game.warn={row:game.p.y,fire:game.time+.85};}if(game.warn&&game.time>=game.warn.fire){const row=game.warn.row;game.fx.push({type:'beam',y:row,t:.3});if(game.p.y===row)hitPlayer(35+Math.min(25,(game.level-1)*5));game.warn=null;game.enemyAt=game.time+1.25;}for(const s of game.shots){s.x+=s.v*dt;if(s.x>=game.e.x-.35&&s.y===game.e.y&&s.x<game.e.x+1){s.x=9;hitEnemy(s.damage);if(!game.running)break;}}game.shots=game.shots.filter(s=>s.x<6.3);game.fx.forEach(f=>f.t-=dt);game.fx=game.fx.filter(f=>f.t>0);$$('[data-use]').forEach((b,i)=>{const t=game.cooldowns[i];b.classList.toggle('used',t>0);b.querySelector('.cooldown').style.width=`${(1-t/8)*100}%`;});}
function pos(col,row){return {x:105+col*128+row*39,y:208+row*72};}
function poly(points,fill,stroke){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}}
function panel(col,row){const p=pos(col,row),warn=game.running&&game.warn?.row===row&&col<3;const fill=warn?(Math.sin(game.time*20)>0?'#b0523e':'#713c32'):col<3?'#24524e':'#59382f';poly([[p.x-55,p.y-24],[p.x+65,p.y-24],[p.x+92,p.y+26],[p.x-28,p.y+26]],'#0b201e');poly([[p.x-55,p.y-29],[p.x+65,p.y-29],[p.x+92,p.y+21],[p.x-28,p.y+21]],fill,col<3?'#43877b':'#975747');poly([[p.x-46,p.y-23],[p.x+60,p.y-23],[p.x+79,p.y+14],[p.x-25,p.y+14]],null,col<3?'#337165':'#7e4c3b');ctx.fillStyle=col<3?'#7dcbb155':'#d79c7155';ctx.fillRect(p.x-24,p.y-2,6,2);ctx.fillRect(p.x+43,p.y-2,6,2);}
function sprite(col,row,enemy=false){const p=pos(col,row),x=Math.round(p.x+10),foot=Math.round(p.y+3+Math.sin(game.time*4)*2);ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(x,p.y+3,30,9,0,0,7);ctx.fill();if(!enemy&&game.p.inv>0&&Math.floor(game.time*20)%2===0)return;const img=sprites[enemy?'enemy':'pulse'];if(img.complete&&img.naturalWidth){const scale=1.35;const recoil=!enemy&&game.time-game.shotAt<.08?-4:0;ctx.drawImage(img,x-48*scale+recoil,foot-90*scale,96*scale,96*scale);}if(!enemy&&game.p.shield>0){ctx.strokeStyle='#bbed7199';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(x,foot-48,43,57,0,0,7);ctx.stroke();}}

function draw(){ctx.clearRect(0,0,1000,490);ctx.fillStyle='#112321';ctx.fillRect(0,0,1000,490);const grad=ctx.createRadialGradient(500,260,10,500,260,550);grad.addColorStop(0,'#213e34');grad.addColorStop(1,'#101c1d');ctx.fillStyle=grad;ctx.fillRect(0,0,1000,490);ctx.strokeStyle='#6cbe8b0b';ctx.lineWidth=1;for(let x=-500;x<1300;x+=65){ctx.beginPath();ctx.moveTo(x,490);ctx.lineTo(500+(x-500)*.4,100);ctx.stroke();}for(let y=110;y<500;y+=28){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1000,y);ctx.stroke();}ctx.fillStyle='#7cbf9d25';for(let i=0;i<30;i++){const x=(i*173+49)%1000,y=(i*97+game.time*7)%490;ctx.fillRect(x,y,2,2);}ctx.font='9px monospace';ctx.fillStyle='#86ad8555';ctx.fillText('PULSE://NET.ARENA',35,125);ctx.fillText('06 × 03 / GRID LINK ACTIVE',760,453);for(let row=0;row<3;row++){for(let col=0;col<6;col++)panel(col,row);}if(game.warn){ctx.font='bold 11px monospace';ctx.fillStyle='#ff9b80';ctx.fillText('! INCOMING',36,pos(0,game.warn.row).y);}sprite(game.p.x,game.p.y);sprite(game.e.x,game.e.y,true);for(const s of game.shots){const p=pos(s.x,s.y);ctx.fillStyle=s.kind==='cannon'?'#fff2a1':'#beef71';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=15;ctx.fillRect(p.x,p.y-48,s.kind==='cannon'?35:19,s.kind==='cannon'?15:7);ctx.shadowBlur=0;}for(const f of game.fx){const p=pos(f.x??0,f.y);if(f.type==='beam'){ctx.globalAlpha=f.t*3;ctx.fillStyle='#f7936f';ctx.fillRect(30,p.y-20,900,8);ctx.globalAlpha=1;}else if(f.type==='thunder'){ctx.strokeStyle='#ddf89f';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(p.x+10,90);ctx.lineTo(p.x-15,p.y-80);ctx.lineTo(p.x+25,p.y-90);ctx.lineTo(p.x,p.y);ctx.stroke();}else if(f.type==='longsword'||f.type==='gold'){ctx.strokeStyle=f.type==='gold'?'#ffe38c':'#b7f9df';ctx.lineWidth=12;ctx.beginPath();ctx.arc(p.x,p.y-35,65,-1.5,1.2);ctx.stroke();}else{ctx.font='bold 24px monospace';ctx.fillStyle=f.type==='heal'?'#c2f57d':f.type==='hurt'?'#ff9d82':'#f4f1bd';ctx.fillText(f.text,p.x-15,p.y-85-(.4-f.t)*40);}}if(game.p.shield>0){ctx.fillStyle='#bbef72';ctx.font='10px monospace';ctx.fillText(`SHIELD ${game.p.shield}`,30,465);}}
function frame(t){const dt=Math.min((t-last)/1000,.05);last=t;if(game.running&&!game.paused)update(dt);draw();requestAnimationFrame(frame);}resetBattle();render();requestAnimationFrame(frame);
